#[test]
fn test_three_segments_of_a_receipt_row_are_one_line_with_three_words() {
    let lines: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let runs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    rt_runs(runs, 1);
    rt_seg(lines, words, 1000, 5000, 1000, 1500, 0);
    rt_seg(lines, words, 8000, 9500, 1010, 1510, 6);
    rt_seg(lines, words, 6500, 6900, 1005, 1500, 3);
    crate::testport::assert_eq(rt_run(lines, words, runs, &mut crate::port::Cells::new(), 3), 1, "name, quantity and price are one row, whatever order the detector emitted them in");
    crate::testport::assert_eq(ln_count(lines), 1, "one line row remains");
    crate::testport::assert_eq(wd_count(words), 3, "the three words are kept");
    crate::testport::assert_eq(ln_get(lines, 0, lh_first()), 0, "the line's words start at the range's first word");
    crate::testport::assert_eq(ln_get(lines, 0, lh_count()), 3, "three words");
    crate::testport::assert_eq(wd_get(words, 0, hd_tstart()), 0, "the name comes first");
    crate::testport::assert_eq(wd_get(words, 1, hd_tstart()), 3, "then the quantity");
    crate::testport::assert_eq(wd_get(words, 2, hd_tstart()), 6, "then the price, in reading order and not in the detector's");
    crate::testport::assert_eq(wd_get(words, 0, hd_line()), 0, "every word names the one line");
    crate::testport::assert_eq(wd_get(words, 2, hd_line()), 0, "every word names the one line");
    crate::testport::assert_eq(ln_get(lines, 0, lh_x0()), 1000, "the line's box is the segments' union: left");
    crate::testport::assert_eq(ln_get(lines, 0, lh_x1()), 9500, "right");
    crate::testport::assert_eq(ln_get(lines, 0, lh_y0()), 1000, "top");
    crate::testport::assert_eq(ln_get(lines, 0, lh_y1()), 1510, "bottom");
    crate::testport::assert_eq(wd_get(words, 0, wf_gap()), 1500, "the gap after the name is the distance to the quantity");
    crate::testport::assert_eq(wd_get(words, 1, wf_gap()), 1100, "and after the quantity the distance to the price");
    crate::testport::assert_eq(wd_get(words, 2, wf_gap()), -1, "none after the last");
}
